namespace Ohirok.PersistentCleanup
{
    /// <summary>
    /// Represents a cleanup action persisted in storage.
    /// </summary>
    public sealed class CleanupRecord
    {
        /// <summary>
        /// Unique identifier of this record. Generated by <see cref="ICleanupService"/> before the record
        /// is saved (a GUID in "N" format), so it is known even if the storage is not configured yet.
        /// </summary>
        public string Id { get; set; }

        /// <summary>
        /// Scope the record belongs to ("" when scopes are not used). A service only sees records of its own scope,
        /// unless it is configured with the wildcard scope "*".
        /// </summary>
        public string Scope { get; set; } = string.Empty;

        /// <summary>
        /// Full name (namespace + type) of the class containing the cleanup method.
        /// Example: "MyProject.UserCleanups".
        /// </summary>
        public string TypeName { get; set; }

        /// <summary>
        /// Method key (from [Cleanup(key)] or the method name).
        /// </summary>
        public string MethodKey { get; set; }

        /// <summary>
        /// Method signature (comma-separated parameter type names).
        /// Example: "System.Int32,System.String". Distinguishes overloads.
        /// </summary>
        public string Signature { get; set; }

        /// <summary>
        /// JSON array of arguments for the cleanup method.
        /// Example: "[123, \"admin@test.com\"]".
        /// </summary>
        public string ArgumentsJson { get; set; }

        /// <summary>
        /// Optional description for logging/debugging.
        /// </summary>
        public string Description { get; set; }

        /// <summary>
        /// When this record was created (UTC).
        /// </summary>
        public DateTime CreatedAt { get; set; }

        /// <summary>
        /// Current status of the cleanup action.
        /// </summary>
        public CleanupStatus Status { get; set; }

        /// <summary>
        /// When the record was last claimed or updated by an execution attempt (UTC).
        /// For a <see cref="CleanupStatus.Processing"/> record this is the "heartbeat" used to detect abandoned records.
        /// </summary>
        public DateTime? LastAttemptAt { get; set; }

        /// <summary>
        /// Number of execution attempts made in the last execution round.
        /// </summary>
        public int AttemptCount { get; set; }

        /// <summary>
        /// Maximum number of attempts per execution round before the record is marked as failed.
        /// </summary>
        public int MaxRetries { get; set; }

        /// <summary>
        /// Error message from the last failed attempt.
        /// </summary>
        public string ErrorMessage { get; set; }

        /// <summary>
        /// Execution order (lower values execute first; records with the same order run in parallel).
        /// </summary>
        public int Order { get; set; }
    }

    /// <summary>
    /// Status of a cleanup record.
    /// </summary>
    public enum CleanupStatus
    {
        /// <summary>
        /// Waiting to be executed.
        /// </summary>
        Pending = 0,

        /// <summary>
        /// Claimed by a run that is executing it now. If the run dies, the record stays in this status
        /// until it becomes stale (see <c>processingTimeoutMinutes</c>) and is then picked up again.
        /// </summary>
        Processing = 1,

        /// <summary>
        /// Successfully completed. Kept for <c>deleteCompletedAfterDays</c> days (0 = deleted immediately).
        /// </summary>
        Completed = 2,

        /// <summary>
        /// Failed after all attempts. Retried by the next <c>PerformAllAsync</c> with a fresh attempt budget.
        /// </summary>
        Failed = 3,

        /// <summary>
        /// The cleanup method is not present in the current code. Re-checked on every <c>PerformAllAsync</c>
        /// and deleted after <c>deleteOrphansAfterDays</c> days.
        /// </summary>
        Orphan = 4
    }
}
